import{z as i,x as s,o as t,c as d,q as n,j as r,D as B,d as a,s as l,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"事件波动","description":"","frontmatter":{"title":"事件波动","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/vt-event-vol.md","filePath":"quant/vt-event-vol.md","lastUpdated":1791413859000}'),C={name:"quant/vt-event-vol.md"};function p(m,E,D,h,u,c){const A=s("Mermaid");return t(),d("div",null,[E[2]||(E[2]=n('<h1 id="事件波动" tabindex="-1">事件波动 <a class="header-anchor" href="#事件波动" aria-label="Permalink to &quot;事件波动&quot;">​</a></h1><div class="epigraph"><p>日历把方差切成两种：事件日的与平常日的；市场为前者付保险费，因为那一天的风险无法分散，也无法像平常日那样摊开。</p><footer>—— 据 Patell and Wolfson, 1981；Ederington and Lee, 1993 整理</footer></div><p><a href="/quant/vt-arbitrage-cases">上一课</a>的案例清单里，事件驱动只占一行；本课把它单独展开，对象从「一段时间的总方差」变成「日程上的那一天」。做市课的<a href="/quant/omm-event-positioning">事件前的仓位管理</a>给了台账、档级与分层减仓；本课站交易台一侧：怎么从期权里读出市场定价的事件方差、怎么建仓、怎么被 IV crush 打。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>同一个到期日的隐含波动同时包含事件日与平常日两部分方差，直接看 IV 谈贵贱没有意义：必须先把事件那一天的份额分解出来。分解错了会两头挨打——把平常日方差的错定价当成事件保险卖出去，或者把真实的跳空风险当成便宜的隐波卖掉。事件方差还有样本量问题：一家公司一年只有四次财报，历史均值的置信区间宽得难以区分贵贱。</p><p><span class="marginnote">术语翻译：「事件方差」就是市场给「公告那一天」单独标价的方差。它藏在同一个到期日的隐含波动里，要用覆盖与不覆盖事件的两条到期报价做差才能拆出来——像从「含门票的套餐价」里减出门票钱。</span></p><h3 id="分解与预测" tabindex="-1">分解与预测 <a class="header-anchor" href="#分解与预测" aria-label="Permalink to &quot;分解与预测&quot;">​</a></h3><p>分解用近月与次月条带的总方差之差：两个到期都覆盖事件日与否的差别，按时间加权归到事件日，得到市场定价的 \\(\\sigma_{\\mathrm{event}}^2\\)。预测腿用事件日已实现方差，但必须横截面池化：同行业的公告按公司加总再加公司项，并剔除结构变化——例如从季度财报转向年度指引，历史分布立刻作废。市场定价的另一样本是<a href="/quant/omm-event-positioning">事件前的仓位管理</a>里的跨式隐含移动：它与条带差分互为校验，对不上先查条款（观察时点、到期日是否真的跨事件）。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三种结构对应三种判断。买事件方差：付保险费换跳空保护，适合底仓不能卖又怕公告的组合，与<a href="/quant/merger-arb-event">并购套利</a>宣布后持有的暴露同构。卖事件方差：吃溢价，必须先问溢价够不够覆盖左尾，并设重进场条件。日历结构：事件方差让近月比远月贵，卖近月买远月把事件单独剥离——与做市课「事件 Gamma 住近月、减仓按期限分层」是同一枚硬币的交易台版本。执行窗口是小时级的：Patell 与 Wolfson 早在 1981 年就记录，公告的价格反应集中在最初几小时；IV 的 crush 通常发生在公告后第一个小时内，跨式买卖两侧都要把窗口写进指令，不能靠盘中手感。</p><p><span class="marginnote">数字实例：财报前跨式隐含移动 ±6%，公告后股价只走了 3.5%——方向赌对了，跨式买家照样亏：因为 6% 里大部分是「事件日方差」的保险费，公告一落地立刻蒸发，这就是 IV crush。</span></p>',11)),(t(),r(o,null,{default:B(()=>[l(A,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CAL%5B%22%E4%BA%8B%E4%BB%B6%E6%97%A5%E5%8E%86%22%5D%20--%3E%20STRIP%5B%22%E8%BF%91%E6%9C%88%E4%B8%8E%E6%AC%A1%E6%9C%88%E6%9D%A1%E5%B8%A6%22%5D%0A%20%20STRIP%20--%3E%20DECOMP%5B%22%E6%97%B6%E9%97%B4%E5%8A%A0%E6%9D%83%E5%B7%AE%E5%88%86%20%E5%BE%97%E4%BA%8B%E4%BB%B6%E6%96%B9%E5%B7%AE%22%5D%0A%20%20DECOMP%20--%3E%20CMP%5B%22%E5%AF%B9%E6%AF%94%E5%8E%86%E5%8F%B2%E4%BA%8B%E4%BB%B6%20RV%20%E6%B1%A0%E5%8C%96%E6%A0%B7%E6%9C%AC%22%5D%0A%20%20CMP%20--%3E%20CHOICE%7B%22%E5%88%A4%E6%96%AD%22%7D%0A%20%20CHOICE%20--%3E%7C%22%E4%BF%9D%E9%99%A9%E4%B8%8D%E8%B6%B3%22%7C%20BUY%5B%22%E4%B9%B0%E4%BA%8B%E4%BB%B6%E6%96%B9%E5%B7%AE%22%5D%0A%20%20CHOICE%20--%3E%7C%22%E6%BA%A2%E4%BB%B7%E8%BF%87%E9%AB%98%22%7C%20SELL%5B%22%E5%8D%96%E4%BA%8B%E4%BB%B6%E6%96%B9%E5%B7%AE%22%5D%0A%20%20CHOICE%20--%3E%7C%22%E8%BF%91%E8%B4%B5%E8%BF%9C%E5%B9%B3%22%7C%20CALT%5B%22%E5%8D%96%E8%BF%91%E6%9C%88%E4%B9%B0%E8%BF%9C%E6%9C%88%22%5D%0A%20%20BUY%20--%3E%20WIN%5B%22%E6%89%A7%E8%A1%8C%E7%AA%97%EF%BC%9A%E5%85%AC%E5%91%8A%E5%89%8D%E5%90%8E%E5%B0%8F%E6%97%B6%E7%BA%A7%22%5D%0A%20%20SELL%20--%3E%20WIN%0A%20%20CALT%20--%3E%20WIN%0A%20%20WIN%20--%3E%20SETTLE%5B%22%E7%BB%93%E7%AE%97%E6%8B%86%E5%88%86%E5%BD%92%E5%9B%A0%22%5D%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("事件溢价为什么存在：那一天的跳空对多数持有人不可分散、也不可在盘中摊平，保险费是时间集中风险的定价。条件化后可以倒挂：市场对高知名度事件（财报、选举）常定价过度，事件已实现方差低于隐含；被忽略的事件（指引电话会、监管听证）反而常定价不足——四问复盘在这里照用：信号对齐事件窗、溢价谁付、崩坏是连续跳、记账按事件日单列。跨名加总有个附加陷阱：组合里几十个名字的事件日在同两周，按 Vega 折算的总暴露看似分散，但公告日"),e("a",{href:"/quant/correlation-breakdown"},"相关性上升"),a("，分散在 events 日集体失效。")],-1)),(t(),r(o,null,{default:B(()=>[l(A,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20PRE%5B%22%E5%85%AC%E5%91%8A%E5%89%8D%3AIV%20%E5%90%AB%E4%BA%8B%E4%BB%B6%E6%97%A5%E6%96%B9%E5%B7%AE%2C%E5%A4%84%E5%9C%A8%E9%AB%98%E4%BD%8D%22%5D%20--%3E%20ANN%5B%22%E5%85%AC%E5%91%8A%E8%90%BD%E5%9C%B0%3A%E4%B8%8D%E7%A1%AE%E5%AE%9A%E6%80%A7%E6%B6%88%E9%99%A4%22%5D%0A%20%20ANN%20--%3E%20CRUSH%5B%22%E4%B8%80%E5%B0%8F%E6%97%B6%E5%86%85%20IV%20%E5%BF%AB%E9%80%9F%E5%9B%9E%E8%90%BD%22%5D%0A%20%20ANN%20--%3E%20GAP%5B%22%E8%B7%B3%E7%A9%BA%3A%E4%BB%B7%E6%A0%BC%E4%B8%80%E6%AC%A1%E6%80%A7%E8%B5%B0%E5%AE%8C%22%5D%0A%20%20CRUSH%20--%3E%20STR%5B%22%E8%B7%A8%E5%BC%8F%E4%B9%B0%E5%AE%B6%3A%E6%96%B9%E5%90%91%E5%AF%B9%E4%BA%86%E4%B9%9F%E5%8F%AF%E8%83%BD%E4%BA%8F%22%5D%0A%20%20GAP%20--%3E%20STR%0A%20%20STR%20--%3E%20WHO%5B%22%E5%8D%96%E6%96%B9%E5%90%83%20crush%2C%E4%B9%B0%E6%96%B9%E4%B8%BA%E5%87%B8%E6%80%A7%E4%BB%98%E4%BF%9D%E9%99%A9%E8%B4%B9%22%5D%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=n('<p><span class="marginnote">财报样本量陷阱：一年四次公告，「事件日方差历史均值」的置信区间宽到难分贵贱。实务用行业横截面池化再加公司随机项，且必须剔除结构性变化——例如改为不发布指引的公司，历史事件方差的下限直接换了一层。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>宏观事件（议息、通胀数据）用同一套分解，但时点与流动性不同：Ederington 与 Lee 记录的日内分布显示信息在公告后几分钟内进价，隐波的衰减路径与财报不同，不能混用参数。0DTE 时代事件 gamma 的做市侧机制见<a href="/quant/amaya-0dte-volatility">0DTE 与波动</a>。本课不写盘前与竞价段的执行细节，也不把「卖事件 IV」当成无条件正期望——倒挂与正溢价都是条件分布。</p><p><span class="marginnote">常见误区：初学者容易把「财报前 IV 总是偏高」读成「卖跨式稳赚」。倒挂只在高知名度事件上出现，而且一次真正的连续跳（并购、退市）能吞掉一整年的保费——所以要设左尾限额与重进场条件，而不是无条件收租。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>事件方差必须从条带差分里分解出来，直接看 IV 谈贵贱没有意义。</li><li>预测腿靠横截面池化，单名样本量不足以支撑判断。</li><li>三种结构：买保险、卖溢价、日历剥离；执行窗口是小时级并写进指令。</li><li>溢价来自不可分散的时间集中风险；条件化后可倒挂，被忽略的事件常定价不足。</li><li>跨名事件日集中时相关性上升，名义分散在事件日失效。</li><li>出处：Patell and Wolfson, 1981；Ederington and Lee, 1993；台账与档级见做市事件课。</li></ul>',6))])}const _=i(C,[["render",p]]);export{T as __pageData,_ as default};
